pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Basic residual score: lower is better
    let base_score = post_residual as f64;

    // Normalized ratios
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    let item_ratio = item_size as f64 / bin_capacity as f64;
    let progress = step_index as f64 / total_items as f64;

    // Residual penalty (steeper for tight fits)
    let mut residual_penalty = residual_ratio.powi(4) * 70.0 * (1.0 + progress * 0.25);
    if progress < 0.3 {
        residual_penalty *= 1.2; // early‑stage penalty boost
    }

    // Large gap penalty
    let large_gap_penalty = if residual_ratio >= 0.92 {
        (residual_ratio - 0.92) * 55.0
    } else {
        0.0
    };

    // Tight‑fit bonus when residual is near zero
    let tight_bonus = if residual_ratio <= 0.0015 { -35.0 } else { 0.0 };

    // Mean residual penalty (weighted)
    let mean_penalty = if residual_ratio > mean_residual * 1.08 {
        (residual_ratio - mean_residual) * 30.0
    } else {
        0.0
    };

    // Open‑bins penalty with non‑linear growth
    let open_penalty = ((open_bins_count as f64).powf(1.2) * 0.3)
        + (open_bins_count as f64 + 1.0).ln() * 0.2;

    // Fragmentation penalty when this is the only fit
    let frag_penalty = if fitting_bins_count == 1 { 6.0 } else { 0.0 };

    // Next item look‑ahead
    let mut next_penalty = 0.0;
    let residual_gap = post_residual as i32 - next_item_size as i32;
    if next_item_size > 0 {
        if residual_gap < 0 {
            // next item does not fit, penalize quadratic gap
            next_penalty = (residual_gap.abs() as f64).powi(2) * 0.2;
        } else if residual_gap == 0 {
            // perfect fit, reward
            next_penalty = -6.0;
        } else if residual_gap <= 3 {
            // small leftover, slight reward
            next_penalty = -2.0;
        } else {
            // moderate leftover, small penalty
            next_penalty = residual_gap as f64 * 0.04;
        }
    }

    // New‑bin handling
    let new_bin_penalty = if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            -70.0
        } else if residual_ratio > 0.80 {
            -12.0
        } else {
            7.0
        }
    } else {
        0.0
    };

    // Size‑to‑residual ratio penalty
    let size_residual_ratio = post_residual as f64 / (item_size as f64 + 1.0);
    let size_penalty = if size_residual_ratio > 1.8 {
        (size_residual_ratio - 1.8) * 6.0
    } else {
        0.0
    };

    // Large item penalty
    let large_item_penalty = if item_ratio > 0.90 && residual_ratio > 0.02 {
        (item_ratio - 0.90) * 10.0
    } else {
        0.0
    };

    // Compactness bonus
    let compactness_bonus = if residual_ratio >= 0.02 && residual_ratio <= 0.05 {
        -12.0
    } else {
        0.0
    };

    // Future‑fit bonus
    let future_fit_bonus = if next_item_size > 0 {
        if next_item_size <= post_residual {
            -4.0
        } else if next_item_size <= post_residual * 3 / 2 {
            -2.0
        } else {
            0.0
        }
    } else {
        0.0
    };

    // Similarity penalty
    let similarity_penalty = if (residual_ratio - mean_residual).abs() < 0.005 {
        4.0
    } else {
        0.0
    };

    // Lookahead gap penalty for large next item
    let lookahead_gap_penalty = if next_item_size > 0
        && next_item_size > bin_capacity / 4
        && residual_ratio < 0.10
    {
        4.0
    } else {
        0.0
    };

    // Open‑bin ratio check
    let open_bins_ratio = open_bins_count as f64 / fitting_bins_count.max(1) as f64;
    let open_bins_ratio_penalty = if open_bins_ratio > 4.0 { 4.0 } else { 0.0 };

    // Dead‑space penalty
    let dead_space_penalty = if next_item_size > 0
        && post_residual > 0
        && post_residual < next_item_size
    {
        post_residual as f64 * 0.12
    } else {
        0.0
    };

    // Fit‑gap penalty for small leftover
    let fit_gap_penalty = if residual_gap > 0 && residual_gap <= 4 {
        residual_gap as f64 * 0.05
    } else {
        0.0
    };

    // Extra penalty when many bins are open but residual is tiny
    let open_bins_small_residual_penalty =
        if residual_ratio < 0.015 && open_bins_count > 12 { 6.0 } else { 0.0 };

    // Extra penalty when bin is almost full but item is large
    let bin_almost_full_large_item_penalty =
        if bin_residual as f64 > bin_capacity as f64 * 0.93 && item_size > bin_capacity / 2 {
            5.0
        } else {
            0.0
        };

    // Sum all components
    base_score
        + residual_penalty
        + large_gap_penalty
        + tight_bonus
        + mean_penalty
        + open_penalty
        + frag_penalty
        + next_penalty
        + new_bin_penalty
        + size_penalty
        + large_item_penalty
        + compactness_bonus
        + future_fit_bonus
        + similarity_penalty
        + lookahead_gap_penalty
        + open_bins_ratio_penalty
        + dead_space_penalty
        + fit_gap_penalty
        + open_bins_small_residual_penalty
        + bin_almost_full_large_item_penalty
