pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // 1. Base residual after placement
    let base = post_residual as f64;

    // 2. Normalised progress
    let progress = step_index as f64 / total_items as f64;

    // 3. Normalised residual of the bin
    let norm_res = post_residual as f64 / bin_capacity as f64;

    // 4. Heavy penalty for large residuals early in the stream
    let early_factor = (1.0 - progress).powi(2);
    let res_pen = norm_res.powi(3) * 45.0 * early_factor;

    // 5. Dead‑space penalty (quadratic in post‑residual)
    let dead_space = norm_res.powi(2) * 25.0 * early_factor;

    // 6. Fit‑ratio penalty: how tightly this item fills the bin before packing
    let fit_ratio = if bin_residual > item_size {
        (bin_residual - item_size) as f64 / bin_capacity as f64
    } else {
        0.0
    };
    let fit_pen = fit_ratio.powi(2) * 30.0 * early_factor;

    // 7. Deviation from the mean residual of all open bins
    let mean_diff = (mean_residual - post_residual as f64).abs();
    let mean_pen = mean_diff.powi(2) * 0.07;

    // 8. Look‑ahead penalty if the next item does not fit
    let next_gap = if next_item_size > 0 {
        (next_item_size as f64 - post_residual as f64).max(0.0)
    } else {
        0.0
    };
    let next_pen = next_gap.powi(2) * 0.4;

    // 9. Penalty for having many open bins (softened)
    let open_pen = ((open_bins_count as f64).ln() + 1.0).powi(2) * 0.012;

    // 10. Bonus when this is the only bin that can fit the item
    let uniq_bonus = if fitting_bins_count == 1 { -35.0 } else { 0.0 };

    // 11. Cost for opening a new bin
    let new_bin_cost = if bin_residual == bin_capacity {
        if fitting_bins_count > 1 {
            15.0
        } else {
            -10.0
        }
    } else {
        0.0
    };

    // 12. Coupling between residual and number of open bins
    let residual_bin_factor = (post_residual as f64 * open_bins_count as f64).powf(0.5) * 0.02;

    // 13. Remaining‑items factor: favour tighter packing when many items left
    let remaining_ratio = (total_items - step_index) as f64 / total_items as f64;
    let remaining_factor = remaining_ratio.powi(2) * 0.02 * norm_res;

    base
        + res_pen
        + dead_space
        + fit_pen
        + mean_pen
        + next_pen
        + open_pen
        + uniq_bonus
        + new_bin_cost
        + residual_bin_factor
        + remaining_factor
}

