    let size_residual_ratio = post_residual as f64 / (item_size as f64 + 1.0);
    let size_penalty = if size_residual_ratio > 3.0 {
        (size_residual_ratio - 3.0) * 5.0
    } else {
        0.0
    };

    // Large‑item penalty – discourage large items that leave noticeable gaps
    let large_item_penalty = if item_ratio > 0.7 && residual_ratio > 0.2 {
        (item_ratio - 0.7) * 5.0
    } else {
        0.0
    };

    // Compactness bonus – prefer residual ratios between 4% and 12%
    let compactness_bonus = if residual_ratio >= 0.04 && residual_ratio <= 0.12 {
        -7.0
    } else {
        0.0
    };

    // Small‑gap fragmentation penalty – penalize residuals ≤ 5
    let small_gap_penalty = if post_residual > 0 && post_residual <= 5 { 3.0 } else { 0.0 };

    // Excess open bins penalty – heavier when many bins are open
    let excess_open_penalty = if open_bins_count > 20 {
        0.6 * (open_bins_count - 20) as f64
    } else {
        0.0
    };

    // Dead‑space penalty – discourage bins with >60% residual
    let dead_space_penalty = if residual_ratio > 0.6 {
        (residual_ratio - 0.6) * 30.0
    } else {
        0.0
    };

    // Future‑fit bonus – reward bins that can snugly fit the next two items
    let future_bonus = if next_item_size > 0 {
        let next2 = next_item_size; // approximate second lookahead
        let diff1 = (post_residual as i32 - next_item_size as i32).abs() as f64;
        let diff2 = (post_residual as i32 - next2 as i32).abs() as f64;
        if diff1 <= 0.04 * bin_capacity as f64 && diff2 <= 0.04 * bin_capacity as f64 {
            -4.0
        } else {
            0.0
        }
    } else {
        0.0
    };

    // Residual‑matching bonus – reward bins whose residual after placement is close to 4% of capacity
    let target_residual = 0.04 * bin_capacity as f64;
    let tolerance = 0.008 * bin_capacity as f64;
    let residual_match_bonus = if (post_residual as f64 - target_residual).abs() <= tolerance {
        -3.0
    } else {
        0.0
    };

    // Additional penalty when global mean is very low and this bin is relatively worse
    let low_mean_adjust = if mean_residual < 0.05 && residual_ratio > mean_residual + 0.02 {
        (residual_ratio - mean_residual - 0.02) * 20.0
    } else {
        0.0
    };

    base_score
        + residual_penalty
        + tight_bonus
        + mean_penalty
        + open_penalty
        + frag_penalty
        + next_penalty
        + new_bin_penalty
        + size_penalty
        + large_item_penalty
        + compactness_bonus
        + small_gap_penalty
        + excess_open_penalty
        + dead_space_penalty
        + future_bonus
        + residual_match_bonus
        + low_mean_adjust
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Basic residual
    let base = post_residual as f64;

    // Normalized ratios
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    let item_ratio = item_size as f64 / bin_capacity as f64;
    let progress = step_index as f64 / total_items as f64;

    // Residual penalty grows with progress
    let residual_penalty = residual_ratio * 55.0 * (1.0 + progress * 0.20);

    // Large gap penalty
    let large_gap_penalty = if residual_ratio >= 0.85 {
        (residual_ratio - 0.85) * 40.0
    } else {
        0.0
    };

    // Tight‑fit bonus
    let tight_bonus = if residual_ratio <= 0.005 { -20.0 } else { 0.0 };

    // Mean residual penalty
    let mean_penalty = if residual_ratio > mean_residual * 1.10 {
        (residual_ratio - mean_residual) * 20.0
    } else {
        0.0
    };

    // Open‑bins penalty with stronger dampening
    let open_penalty =
        ((open_bins_count as f64 + 1.0).sqrt() * 0.40) + (open_bins_count as f64 + 1.0).ln() * 0.15;

    // Fragmentation penalty when this is the only fit
    let frag_penalty = if fitting_bins_count == 1 { 4.0 } else { 0.0 };

    // Next item look‑ahead
    let next_penalty = if next_item_size > 0 {
        if next_item_size > post_residual {
            let diff = (next_item_size as f64 - post_residual as f64).max(0.0);
            diff * diff * 0.15
        } else {
            -1.5
        }
    } else {
        0.0
    };

    // New‑bin handling
    let new_bin_penalty = if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            -45.0
        } else if residual_ratio > 0.60 {
            -4.0
        } else {
            6.0
        }
    } else {
        0.0
    };

    // Size‑to‑residual ratio penalty
    let size_residual_ratio = post_residual as f64 / (item_size as f64 + 1.0);
    let size_penalty = if size_residual_ratio > 2.0 {
        (size_residual_ratio - 2.0) * 5.0
    } else {
        0.0
    };

    // Large item penalty
    let large_item_penalty = if item_ratio > 0.90 && residual_ratio > 0.02 {
        (item_ratio - 0.90) * 8.0
    } else {
        0.0
    };

    // Compactness bonus
    let compactness_bonus = if residual_ratio >= 0.02 && residual_ratio <= 0.08 {
        -8.0
    } else {
        0.0
    };

    // Future‑fit bonus
    let future_fit_bonus = if next_item_size > 0 {
        if next_item_size <= post_residual {
            -2.0
        } else if next_item_size <= bin_capacity / 4 {
            -0.5
        } else {
            0.0
        }
    } else {
        0.0
    };

    // Similarity penalty
    let similarity_penalty = if (residual_ratio - mean_residual).abs() < 0.015 {
        3.0
    } else {
        0.0
    };

    // Additional lookahead for large next item
    let lookahead_gap_penalty = if next_item_size > 0
        && next_item_size > bin_capacity / 2
        && residual_ratio < 0.20
    {
        5.0
    } else {
        0.0
    };

    // Open‑bin ratio check
    let open_bins_ratio = open_bins_count as f64 / fitting_bins_count.max(1) as f64;
    let open_bins_ratio_penalty = if open_bins_ratio > 5.0 { 2.0 } else { 0.0 };

    // Sum all components
    base
        + residual_penalty
        + large_gap_penalty
        + tight_bonus
        + mean_penalty
        + open_penalty
        + frag_penalty
        + next_penalty
        + new_bin_penalty
        + size_penalty
        + large_item_penalty
        + compactness_bonus
        + future_fit_bonus
        + similarity_penalty
        + lookahead_gap_penalty
        + open_bins_ratio_penalty
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: remaining space after placement (lower is better)
    let base = post_residual as f64;

    // Progress in the stream
    let progress = step_index as f64 / total_items as f64;
    let early_factor = (1.0 - progress).powi(3);

    // Normalised residuals before and after placement
    let norm_pre = bin_residual as f64 / bin_capacity as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;

    // Penalty for leaving residual too large (cubic)
    let residual_penalty = (1.0 - norm_post).powi(3) * early_factor * 15.0;

    // Deviation from mean residual (quadratic)
    let mean_diff = (mean_residual - post_residual as f64).abs();
    let mean_penalty = mean_diff.powi(2) * 0.04;

    // Next‑item look‑ahead penalty
    let next_gap = if next_item_size > 0 {
        ((next_item_size as f64) - post_residual as f64).max(0.0)
    } else {
        0.0
    };
    let next_penalty = next_gap.powi(2) * 0.35;

    // Open‑bins penalty with a decay that slows later
    let open_decay = (1.0 - progress).powf(0.6);
    let open_penalty = (open_bins_count as f64).powf(1.4) * 0.012 * open_decay;

    // Bonus if this bin is the only one that can fit the item
    let fitting_bonus = if fitting_bins_count == 1 { -30.0 } else { 0.0 };

    // Bonus for opening a brand‑new bin
    let empty_bonus = if bin_residual == bin_capacity {
        if fitting_bins_count == 0 { -25.0 } else { -12.0 }
    } else {
        0.0
    };

    // Variance penalty for drastic residual change
    let variance_penalty = ((norm_pre - norm_post).abs().powi(2)) * 0.04;

    // Dead‑space penalty when residual is large relative to capacity
    let dead_space_bonus = if bin_residual > bin_capacity * 3 / 4 {
        -4.0
    } else {
        0.0
    };

    // Large‑item penalty: avoid leaving a tiny residual after a big item
    let large_item_penalty = if item_size as f64 > (bin_capacity as f64 * 0.7) {
        let tiny_residual = post_residual as f64 / bin_capacity as f64;
        if tiny_residual < 0.08 { 10.0 } else { 0.0 }
    } else {
        0.0
    };

    // Ratio penalty: residual too large compared to the item
    let ratio_penalty = if post_residual > item_size * 3 { 5.0 } else { 0.0 };

    // Fit‑ratio bonus/penalty: how tightly the item fits the bin
    let fit_ratio = if bin_residual > 0 {
        item_size as f64 / bin_residual as f64
    } else {
        0.0
    };
    let fit_penalty = if fit_ratio > 0.9 {
        -8.0
    } else if fit_ratio < 0.5 {
        6.0
    } else {
        0.0
    };

    // Density bonus for a high ratio of open bins to items processed
    let open_density = open_bins_count as f64 / total_items as f64;
    let density_penalty = if open_density > 0.05 { open_penalty * 1.2 } else { 0.0 };

    // Early‑open bonus: encourage opening new bins early
    let early_open_bonus = if bin_residual == bin_capacity && progress < 0.2 {
        -15.0
    } else {
        0.0
    };

    // Extra penalty if residual is far above the mean residual
    let excess_mean_penalty = if post_residual > (mean_residual as u32 + bin_capacity / 10) {
        3.0
    } else {
        0.0
    };

    base
        + residual_penalty
        + mean_penalty
        + next_penalty
        + open_penalty
        + fitting_bonus
        + empty_bonus
        + variance_penalty
        + dead_space_bonus
        + large_item_penalty
        + ratio_penalty
        + fit_penalty
        + density_penalty
        + early_open_bonus
        + excess_mean_penalty
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
