    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    let item_ratio = item_size as f64 / bin_capacity as f64;
    let progress = step_index as f64 / total_items as f64;

    // Residual penalty: stronger near zero
    let residual_penalty = residual_ratio.powi(3) * 80.0 * (1.0 + progress * 0.20);

    // Large gap penalty
    let large_gap_penalty = if residual_ratio >= 0.90 {
        (residual_ratio - 0.90) * 60.0
    } else {
        0.0
    };

    // Tight‑fit bonus when residual is almost zero
    let tight_bonus = if residual_ratio <= 0.002 { -30.0 } else { 0.0 };

    // Mean residual penalty
    let mean_penalty = if residual_ratio > mean_residual * 1.05 {
        (residual_ratio - mean_residual) * 24.0
    } else {
        0.0
    };

    // Open‑bins penalty with stronger dampening
    let open_penalty =
        ((open_bins_count as f64 + 1.0).sqrt() * 0.40) + (open_bins_count as f64 + 1.0).ln() * 0.25;

    // Fragmentation penalty when this is the only fit
    let frag_penalty = if fitting_bins_count == 1 { 4.0 } else { 0.0 };

    // Next item look‑ahead
    let mut next_penalty = 0.0;
    let residual_gap = post_residual as i32 - next_item_size as i32;
    if next_item_size > 0 {
        if residual_gap < 0 {
            // next item does not fit, penalize proportional to absolute gap
            next_penalty = (residual_gap.abs() as f64).powi(2) * 0.15;
        } else if residual_gap == 0 {
            // perfect fit, reward
            next_penalty = -4.0;
        } else if residual_gap < 5 {
            // small leftover, slight reward
            next_penalty = -1.5;
        } else {
            // moderate leftover, small penalty
            next_penalty = residual_gap as f64 * 0.03;
        }
    }

    // New‑bin handling
    let new_bin_penalty = if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            -50.0
        } else if residual_ratio > 0.60 {
            -8.0
        } else {
            5.0
        }
    } else {
        0.0
    };

    // Size‑to‑residual ratio penalty
    let size_residual_ratio = post_residual as f64 / (item_size as f64 + 1.0);
    let size_penalty = if size_residual_ratio > 2.0 {
        (size_residual_ratio - 2.0) * 5.0
    } else {
        0.0
    };

    // Large item penalty
    let large_item_penalty = if item_ratio > 0.95 && residual_ratio > 0.01 {
        (item_ratio - 0.95) * 8.0
    } else {
        0.0
    };

    // Compactness bonus
    let compactness_bonus = if residual_ratio >= 0.03 && residual_ratio <= 0.06 {
        -10.0
    } else {
        0.0
    };

    // Future‑fit bonus
    let future_fit_bonus = if next_item_size > 0 {
        if next_item_size <= post_residual {
            -3.0
        } else if next_item_size <= post_residual * 2 {
            -1.0
        } else {
            0.0
        }
    } else {
        0.0
    };

    // Similarity penalty
    let similarity_penalty = if (residual_ratio - mean_residual).abs() < 0.01 {
        3.0
    } else {
        0.0
    };

    // Additional lookahead for large next item
    let lookahead_gap_penalty = if next_item_size > 0
        && next_item_size > bin_capacity / 3
        && residual_ratio < 0.15
    {
        3.0
    } else {
        0.0
    };

    // Open‑bin ratio check
    let open_bins_ratio = open_bins_count as f64 / fitting_bins_count.max(1) as f64;
    let open_bins_ratio_penalty = if open_bins_ratio > 5.0 { 3.0 } else { 0.0 };

    // Dead‑space penalty: residual positive but smaller than next item
    let dead_space_penalty = if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        post_residual as f64 * 0.10
    } else {
        0.0
    };

    // Fit‑gap penalty for small leftover after placing item
    let fit_gap_penalty = if residual_gap > 0 && residual_gap <= 5 {
        residual_gap as f64 * 0.04
    } else {
        0.0
    };

    // Extra penalty when many bins are open but residual is tiny
    let open_bins_small_residual_penalty =
        if residual_ratio < 0.02 && open_bins_count > 10 { 5.0 } else { 0.0 };

    // Extra penalty when bin is almost full but item is large
    let bin_almost_full_large_item_penalty =
        if bin_residual as f64 > bin_capacity as f64 * 0.90 && item_size > bin_capacity / 2 {
            4.0
        } else {
            0.0
        };

    // Summation of all components
    base
        + residual_penalty
        + large_gap_penalty
        + tight_bonus
        + mean_penalty
        + open_penalty
        + frag_penalty
        + next_penalty
        + new_bin_penalty
        + size_penalty
        + large_item_penalty
        + compactness_bonus
        + future_fit_bonus
        + similarity_penalty
        + lookahead_gap_penalty
        + open_bins_ratio_penalty
        + dead_space_penalty
        + fit_gap_penalty
        + open_bins_small_residual_penalty
        + bin_almost_full_large_item_penalty
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: remaining space after placement (lower is better)
    let base = post_residual as f64;

    // Stream progress factor
    let progress = step_index as f64 / total_items as f64;
    let early_weight = (1.0 - progress).powi(2);

    // Normalised residuals before and after placement
    let norm_pre = bin_residual as f64 / bin_capacity as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;

    // Deviation from mean residual (quadratic)
    let mean_diff = (mean_residual - post_residual as f64).abs();
    let mean_penalty = mean_diff.powi(2) * 0.05;

    // Cubic residual penalty, weighted by early progress
    let residual_penalty = (1.0 - norm_post).powi(3) * early_weight * 18.0;

    // Next‑item look‑ahead: penalise leaving a gap too large for the next item
    let next_diff = if next_item_size > 0 {
        ((next_item_size as f64) - post_residual as f64).max(0.0)
    } else {
        0.0
    };
    let next_penalty = next_diff.powi(2) * 0.40;

    // Penalty for many open bins, decaying with progress
    let open_decay = (1.0 - progress).powf(0.5);
    let open_penalty = (open_bins_count as f64).powf(1.5) * 0.015 * open_decay;

    // Bonus when this bin is the only one that can fit the item
    let fitting_bonus = if fitting_bins_count == 1 { -25.0 } else { 0.0 };

    // Bonus for opening a new bin when no current bin fits
    let empty_bonus = if bin_residual == bin_capacity {
        if fitting_bins_count == 0 { -20.0 } else { -10.0 }
    } else { 0.0 };

    // Penalise drastic change in residual after placement
    let variance_penalty = ((norm_pre - norm_post).abs().powi(2)) * 0.05;

    // Dead‑space bonus: discourage leaving a large empty chunk when the bin is almost full
    let dead_space_bonus = if bin_residual > bin_capacity * 2 / 3 {
        -5.0
    } else {
        0.0
    };

    // Large‑item penalty: if the item is a sizeable fraction of the bin, avoid leaving a tiny residual
    let large_item_penalty = if item_size as f64 > (bin_capacity as f64 * 0.6) {
        let tiny_residual = post_residual as f64 / bin_capacity as f64;
        if tiny_residual < 0.1 { 8.0 } else { 0.0 }
    } else {
        0.0
    };

    // Ratio‑based penalty: avoid leaving a residual much larger than the item size
    let ratio_penalty = if post_residual > item_size * 2 {
        4.0
    } else {
        0.0
    };

    base
        + residual_penalty
        + mean_penalty
        + next_penalty
        + open_penalty
        + fitting_bonus
        + empty_bonus
        + variance_penalty
        + dead_space_bonus
        + large_item_penalty
        + ratio_penalty
}
